(** ** The lap *)

Lemma lap_1RB1LB_0LC0RA_1RA0LD_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LB_0LC0RA_1RA0LD_1RA1LC B0_1RB1LB_0LC0RA_1RA0LD_1RA1LC B1_1RB1LB_0LC0RA_1RA0LD_1RA1LC 4 12 p j' [] []).
    + exact run_ovf_1RB1LB_0LC0RA_1RA0LD_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j' E).
    + exact (geo_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LB_0LC0RA_1RA0LD_1RA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LB_0LC0RA_1RA0LD_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LB_0LC0RA_1RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LB_0LC0RA_1RA0LD_1RA1LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LB_0LC0RA_1RA0LD_1RA1LC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LB_0LC0RA_1RA0LD_1RA1LC : forall t, ~ In t pins_1RB1LB_0LC0RA_1RA0LD_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LB_0LC0RA_1RA0LD_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 6; SWinL 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LB_0LC0RA_1RA0LD_1RA1LC (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LB_0LC0RA_1RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LB_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LB_0LC0RA_1RA0LD_1RA1LC : NeverQuasiHaltsTr tm_1RB1LB_0LC0RA_1RA0LD_1RA1LC.
Proof.
  apply (glue_neverqhtr tm_1RB1LB_0LC0RA_1RA0LD_1RA1LC pins_1RB1LB_0LC0RA_1RA0LD_1RA1LC Cc 1).
  - exact boot_1RB1LB_0LC0RA_1RA0LD_1RA1LC.
  - intros p _. apply lap_1RB1LB_0LC0RA_1RA0LD_1RA1LC.
  - intros t Ht p _. apply fire_1RB1LB_0LC0RA_1RA0LD_1RA1LC. exact Ht.
Qed.

Theorem nonhalt_1RB1LB_0LC0RA_1RA0LD_1RA1LC : NonHalt tm_1RB1LB_0LC0RA_1RA0LD_1RA1LC.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1LB_0LC0RA_1RA0LD_1RA1LC. Qed.

