Lemma fire_1RB1LB_0RC0LA_0RD1RD_1LA1RC : forall t, ~ In t pins_1RB1LB_0RC0LA_0RD1RD_1LA1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
