    apply (fire_via_ovf_lift tm Cc lapil_1RB1LB_0RC0LA_0RD1RD_1LA1RC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LB_0RC0LA_0RD1RD_1LA1RC [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
