(** The chain into this family lands on its anchor up to 2/1
    trailing blanks. *)
Lemma gbo_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall j, lift (cden [] [] j BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC = (StC, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB1LB_0RC1LA_1RD0LB_1LB1RC. rewrite epow2_1RB1LB_0RC1LA_1RD0LB_1LB1RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
