(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LB_0RC1LA_1RD0LB_1LB1RC.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LB_0RC1LA_1RD0LB_1LB1RC, cden, BE0_1RB1LB_0RC1LA_1RD0LB_1LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LB_0RC1LA_1RD0LB_1LB1RC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LB_0RC1LA_1RD0LB_1LB1RC p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC).
    split; [lia|]. split; [| exact (gbo_1RB1LB_0RC1LA_1RD0LB_1LB1RC j)].
    rewrite (gso_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j E).
    exact (srun_sound tm true true chb_1RB1LB_0RC1LA_1RD0LB_1LB1RC B0_1RB1LB_0RC1LA_1RD0LB_1LB1RC BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC 4 8
             run_boot_1RB1LB_0RC1LA_1RD0LB_1LB1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 13), (cden [] [] j B1_1RB1LB_0RC1LA_1RD0LB_1LB1RC).
    split; [| exact (geo_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j E)].
    rewrite (gxi_1RB1LB_0RC1LA_1RD0LB_1LB1RC j).
    exact (srun_sound tm true true che_1RB1LB_0RC1LA_1RD0LB_1LB1RC BE0_1RB1LB_0RC1LA_1RD0LB_1LB1RC B1_1RB1LB_0RC1LA_1RD0LB_1LB1RC 4 13
             run_exit_1RB1LB_0RC1LA_1RD0LB_1LB1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LB_0RC1LA_1RD0LB_1LB1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 15.
  assert (H : match csteps tm 15 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LB_0RC1LA_1RD0LB_1LB1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LB_0RC1LA_1RD0LB_1LB1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LB_0RC1LA_1RD0LB_1LB1RC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC). split;
      [| exact (gbo_1RB1LB_0RC1LA_1RD0LB_1LB1RC j)].
    rewrite (gso_1RB1LB_0RC1LA_1RD0LB_1LB1RC p j E).
    exact (srun_sound tm true true chb_1RB1LB_0RC1LA_1RD0LB_1LB1RC B0_1RB1LB_0RC1LA_1RD0LB_1LB1RC BB1_1RB1LB_0RC1LA_1RD0LB_1LB1RC 4 8
             run_boot_1RB1LB_0RC1LA_1RD0LB_1LB1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LB_0RC1LA_1RD0LB_1LB1RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LB_0RC1LA_1RD0LB_1LB1RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LB_0RC1LA_1RD0LB_1LB1RC : forall t, ~ In t pins_1RB1LB_0RC1LA_1RD0LB_1LB1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LB_0RC1LA_1RD0LB_1LB1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LB_0RC1LA_1RD0LB_1LB1RC (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LB_0RC1LA_1RD0LB_1LB1RC [SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LB_0RC1LA_1RD0LB_1LB1RC [SCycL 2 0; SWin 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LB_0RC1LA_1RD0LB_1LB1RC [SCycL 2 0; SWin 4; SCycR 2; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LB_0RC1LA_1RD0LB_1LB1RC [SCycL 2 0; SWin 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LB_0RC1LA_1RD0LB_1LB1RC [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LB_0RC1LA_1RD0LB_1LB1RC [SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
