(** 1RB1LB_0RC1RB_1LD0RB_0LD1LA *)
(** 1RB1LB_0RC1RB_1LD0RB_0LD1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LB_0RC1RB_1LD0RB_0LD1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S1 DL StA end.

(** Its mirror 1LB1RB_0LC1LB_1RD0LB_0RD1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LB_0RC1RB_1LD0RB_0LD1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LB_0RC1RB_1LD0RB_0LD1LA : list Instr := [].
Definition tmw_1RB1LB_0RC1RB_1LD0RB_0LD1LA : TM := tm_wrap_trs tmm_1RB1LB_0RC1RB_1LD0RB_0LD1LA pins_1RB1LB_0RC1RB_1LD0RB_0LD1LA.
Local Notation tm := tmw_1RB1LB_0RC1RB_1LD0RB_0LD1LA.

Lemma mirror_ok_1RB1LB_0RC1RB_1LD0RB_0LD1LA : mirror_tm tm_1RB1LB_0RC1RB_1LD0RB_0LD1LA = tmm_1RB1LB_0RC1RB_1LD0RB_0LD1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

