(** 1RB1LB_1LA0RC_0LB0LD_0RD0RC *)
Definition tm_1RB1LB_1LA0RC_0LB0LD_0RD0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LB_1LA0RC_0LB0LD_0RD0RC : list Instr := [].
Definition tmw_1RB1LB_1LA0RC_0LB0LD_0RD0RC : TM := tm_wrap_trs tm_1RB1LB_1LA0RC_0LB0LD_0RD0RC pins_1RB1LB_1LA0RC_0LB0LD_0RD0RC.
Local Notation tm := tmw_1RB1LB_1LA0RC_0LB0LD_0RD0RC.

Definition Cc_1RB1LB_1LA0RC_0LB0LD_0RD0RC (p : positive) : cconf := (StB, (Ap_Alph_00_10_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1LB_1LA0RC_0LB0LD_0RD0RC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LB_1LA0RC_0LB0LD_0RD0RC : sconf := mkC StB (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LB_1LA0RC_0LB0LD_0RD0RC : sconf := mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [S0] [] 0 0 []).
Definition chz_1RB1LB_1LA0RC_0LB0LD_0RD0RC : list lstep := [SWin 2; SWinR 2].

Lemma run_z_1RB1LB_1LA0RC_0LB0LD_0RD0RC : srun tm false true chz_1RB1LB_1LA0RC_0LB0LD_0RD0RC Z0_1RB1LB_1LA0RC_0LB0LD_0RD0RC = Some (Z1_1RB1LB_1LA0RC_0LB0LD_0RD0RC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
