Definition P0_1RB1LB_1LA0RC_0LB0LD_0RD0RC : sconf := mkC StB (mkS [S1;S0] [S1;S0] 1 0 [S0;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1LB_1LA0RC_0LB0LD_0RD0RC : sconf := mkC StB (mkS [S0;S0] [S0;S0] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chp_1RB1LB_1LA0RC_0LB0LD_0RD0RC : list lstep := [SWin 2; SCycL 2 0; SWin 2; SRotR 1; SWin 3; SCycR 4; SWin 1; SWinR 2; SRotL 1].

Lemma run_p_1RB1LB_1LA0RC_0LB0LD_0RD0RC : srun tm false true chp_1RB1LB_1LA0RC_0LB0LD_0RD0RC P0_1RB1LB_1LA0RC_0LB0LD_0RD0RC = Some (P1_1RB1LB_1LA0RC_0LB0LD_0RD0RC, 6, 10).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LB_1LA0RC_0LB0LD_0RD0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
