(** ** The lap *)

Lemma lap_1RB1LB_1LA0RC_0LD1RC_1LB0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
