  - destruct (lapi_1RB1LB_1LA0RC_0LD1RC_1LB0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LB_1LA0RC_0LD1RC_1LB0RC B0_1RB1LB_1LA0RC_0LD1RC_1LB0RC B1_1RB1LB_1LA0RC_0LD1RC_1LB0RC 4 12 p j' [] []).
    + exact run_ovf_1RB1LB_1LA0RC_0LD1RC_1LB0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LB_1LA0RC_0LD1RC_1LB0RC p j' E).
    + exact (geo_1RB1LB_1LA0RC_0LD1RC_1LB0RC p j' E).
    + lia.
