            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LB_1LA0RC_0LD1RC_1LB0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LB_1LA0RC_0LD1RC_1LB0RC
      with (l := [SRotL 1; SWin 3; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LB_1LA0RC_0LD1RC_1LB0RC
      with (l := [SRotL 1; SWin 3; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
