    apply (lap_of_run tm Cc true true cho_1RB1LB_1LA0RC_1RD1RC_0LD0LB B0_1RB1LB_1LA0RC_1RD1RC_0LD0LB B1_1RB1LB_1LA0RC_1RD1RC_0LD0LB 4 10 p j' [] []).
