  split; [lia|]. split; [| exact (gei_1RB1LB_1LC0LA_0RD0RD_1LA1RD p j q0 E)].
  rewrite (gsi_1RB1LB_1LC0LA_0RD0RD_1LA1RD p j q0 E).
  exact (srun_sound tm false true chi_1RB1LB_1LC0LA_0RD0RD_1LA1RD A0_1RB1LB_1LC0LA_0RD0RD_1LA1RD A1_1RB1LB_1LC0LA_0RD0RD_1LA1RD 4 20
