  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB1LB_1LC0RD_0RC1LA_0LA1RD p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 8), (cden [] [] j BB1_1RB1LB_1LC0RD_0RC1LA_0LA1RD).
      split; [lia|]. split; [| exact (gbo_1RB1LB_1LC0RD_0RC1LA_0LA1RD j)].
