  apply (fire_of_run_instr tm Cc true true l B0_1RB1LB_1LC0RD_0RC1LA_0LA1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LB_1LC0RD_0RC1LA_0LA1RD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1LB_1LC0RD_0RC1LA_0LA1RD : forall (l : list lstep) (t : Instr),
