(** ** The lap *)

Lemma lap_1RB1LB_1RC0RA_1LD1RB_1LA0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
