(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LB_1RC0RC_1LD0LA_1LA0RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j A0_1RB1LB_1RC0RC_1LD0LA_1LA0RD.
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p j q0 E) as (H1 & _).
  unfold Cc_1RB1LB_1RC0RC_1LD0LA_1LA0RD, cden, A0_1RB1LB_1RC0RC_1LD0LA_1LA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LB_1RC0RC_1LD0LA_1LA0RD : forall p j q0, cview p = (j, Some q0) ->
  cden (Dp q0 ++ [S0]) [] j A1_1RB1LB_1RC0RC_1LD0LA_1LA0RD = Cc (Pos.succ p).
