Lemma lapi_1RB1LB_1RC0RC_1LD0LA_1LA0RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (8 * j + 16). split; [lia|].
  rewrite (gsi_1RB1LB_1RC0RC_1LD0LA_1LA0RD p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LB_1RC0RC_1LD0LA_1LA0RD A0_1RB1LB_1RC0RC_1LD0LA_1LA0RD A1_1RB1LB_1RC0RC_1LD0LA_1LA0RD 8 16
             run_int_1RB1LB_1RC0RC_1LD0LA_1LA0RD (Dp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LB_1RC0RC_1LD0LA_1LA0RD p j q0 E).
