Lemma gso_1RB1LB_1RC0RC_1LD0LA_1LA0RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LB_1RC0RC_1LD0LA_1LA0RD.
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (H1 & _).
  unfold Cc_1RB1LB_1RC0RC_1LD0LA_1LA0RD, cden, B0_1RB1LB_1RC0RC_1LD0LA_1LA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
